code='''def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    cols = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
        cols.setdefault(c, []).append(r)
    # The aligned pair defines the main axis; connect every other point to it.
    h = [(r, cs) for r, cs in rows.items() if len(cs) >= 2]
    v = [(c, rs) for c, rs in cols.items() if len(rs) >= 2]
    if h:
        r, cs = max(h, key=lambda item: max(item[1]) - min(item[1]))
        for c in range(min(cs), max(cs) + 1):
            if out[r][c] == 0: out[r][c] = 3
        for pr, pc in points:
            if pr != r:
                for rr in range(min(pr, r), max(pr, r) + 1):
                    if out[rr][pc] == 0: out[rr][pc] = 3
    elif v:
        c, rs = max(v, key=lambda item: max(item[1]) - min(item[1]))
        for r in range(min(rs), max(rs) + 1):
            if out[r][c] == 0: out[r][c] = 3
        for pr, pc in points:
            if pc != c:
                for cc in range(min(pc, c), max(pc, c) + 1):
                    if out[pr][cc] == 0: out[pr][cc] = 3
    return out
'''
